using System;
using System.Net;
using System.IO;

class HelloHttpServer
{
    static void Main(string[] args)
    {
        // Création d'un objet HttpListener
        HttpListener listener = new HttpListener();
        listener.Port = 8080; // Le port 8080 est utilisé
        listener.Prefixes.Add("http://localhost:8080/"); // La racine de l'application

        // Début du serveur
        listener.Start();

        Console.WriteLine("Server started. Listening on port 8080...");

        while (true)
        {
            // Attente d'une requête
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            HttpListenerRequest request = context.Request;
            string url = request.Url.LocalPath;
            if (url == "/hello") // Si la requête est pour la page "hello"
            {
                string response = "Hello"; // Le contenu de la réponse
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response); // Encodage en byte[]
                context.Response.ContentLength64 = buffer.Length; // Taille du contenu de la réponse
                context.Response.OutputStream.Write(buffer, 0, buffer.Length); // Écriture du contenu de la réponse
                context.Response.Close(); // Fermeture de la réponse
            }
            else
            {
                // Erreur 404 si la requête n'est pas pour la page "hello"
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Not Found";
                context.Response.Close();
            }
        }
    }
}
```
